begin;
create function pg_temp.check_finance(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',label; end if; end; $$;
create function pg_temp.deny_finance(statement text,code text) returns void language plpgsql as $$ begin begin execute statement; exception when others then if sqlstate=code then return; end if; raise; end; raise exception 'Unexpected success: %',statement; end; $$;
insert into auth.users(id,email,raw_user_meta_data) values
('11111111-1111-4111-8111-111111111111','finance-a@example.test','{"company_name":"Finance A"}'),
('22222222-2222-4222-8222-222222222222','finance-b@example.test','{"company_name":"Finance B"}');
select set_config('finance.company_a',(select id::text from public.companies where owner_id='11111111-1111-4111-8111-111111111111'),true);
select set_config('finance.company_b',(select id::text from public.companies where owner_id='22222222-2222-4222-8222-222222222222'),true);
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select set_config('finance.sale',public.nexo_finance_command('create','{"request_id":"00000000-0000-4000-8000-000000000001","kind":"sale","description":"Venda janeiro","category":"Serviços","occurred_on":"2026-01-20","due_on":"2026-02-20","amount_cents":10001}')::text,true);
select pg_temp.check_finance((public.nexo_finance_command('create','{"request_id":"00000000-0000-4000-8000-000000000001"}')->>'id')=(current_setting('finance.sale')::jsonb->>'id'),'retry returns original sale');
select set_config('finance.payment',public.nexo_finance_command('pay',jsonb_build_object('request_id','00000000-0000-4000-8000-000000000002','operation_id',current_setting('finance.sale')::jsonb->>'id','amount_cents',4000,'paid_on','2026-02-01','method','pix'))::text,true);
select pg_temp.check_finance((public.nexo_finance_command('pay','{"request_id":"00000000-0000-4000-8000-000000000002"}')->>'id')=(current_setting('finance.payment')::jsonb->>'id'),'retry returns original payment');
select pg_temp.check_finance((public.nexo_finance_page('2026-01-01')->'summary'->>'sales_cents')='10001','revenue in January');
select pg_temp.check_finance((public.nexo_finance_page('2026-01-01')->'summary'->>'received_cents')='0','no false January cash');
select pg_temp.check_finance((public.nexo_finance_page('2026-02-01')->'summary'->>'received_cents')='4000','cash in February');
select pg_temp.check_finance((public.nexo_finance_page('2026-02-01')->'summary'->>'receivable_cents')='6001','partial payment exact cents');
select pg_temp.deny_finance(format('select public.nexo_finance_command(''pay'',%L::jsonb)',jsonb_build_object('request_id',gen_random_uuid(),'operation_id',current_setting('finance.sale')::jsonb->>'id','amount_cents',6002,'paid_on','2026-02-02','method','pix')),'22023');
select pg_temp.deny_finance(format('select public.nexo_finance_command(''pay'',%L::jsonb)',jsonb_build_object('request_id',gen_random_uuid(),'operation_id',current_setting('finance.sale')::jsonb->>'id','amount_cents',1.5,'paid_on','2026-02-02','method','pix')),'22023');
select pg_temp.deny_finance(format('select public.nexo_finance_command(''pay'',%L::jsonb)',jsonb_build_object('request_id',gen_random_uuid(),'operation_id',current_setting('finance.sale')::jsonb->>'id','amount_cents',1,'paid_on','2999-02-02','method','pix')),'22023');
select pg_temp.deny_finance(format('select public.nexo_finance_command(''void_operation'',%L::jsonb)',jsonb_build_object('id',current_setting('finance.sale')::jsonb->>'id','reason','Correção')),'55000');
select pg_temp.deny_finance('update public.operations set amount_cents=0','42501');
select pg_temp.deny_finance('delete from public.payments','42501');
select pg_temp.deny_finance('insert into public.operations(company_id) values(gen_random_uuid())','42501');
select public.nexo_finance_command('create','{"request_id":"00000000-0000-4000-8000-000000000003","kind":"expense","description":"Material janeiro","category":"Produtos","occurred_on":"2026-01-10","due_on":"2026-01-30","amount_cents":2000}');
select pg_temp.check_finance((public.nexo_finance_page('2026-01-01','sale','Venda')->>'total')='1','server filters with exact total');
select pg_temp.check_finance((public.nexo_finance_page('2026-01-01','all','%')->>'total')='0','search treats SQL wildcard literally');
select pg_temp.check_finance((public.nexo_finance_page('2026-01-01')->'summary'->>'expenses_cents')='2000','expense competence');
select pg_temp.check_finance(jsonb_array_length(public.nexo_export_company_data()->'operations')=2,'backup includes financial records');
select pg_temp.check_finance(jsonb_array_length(public.nexo_export_company_data()->'payments')=1,'backup includes payments');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select pg_temp.check_finance((select count(*) from public.operations)=0,'RLS hides operations');
select pg_temp.check_finance((select count(*) from public.payments)=0,'RLS hides payments');
select pg_temp.check_finance(public.nexo_operation_detail((current_setting('finance.sale')::jsonb->>'id')::uuid) is null,'detail cannot cross companies');
select pg_temp.check_finance((public.nexo_finance_page('2026-01-01')->>'total')='0','summary cannot cross companies');
select pg_temp.deny_finance(format('select public.nexo_finance_command(''pay'',%L::jsonb)',jsonb_build_object('request_id',gen_random_uuid(),'operation_id',current_setting('finance.sale')::jsonb->>'id','amount_cents',1,'paid_on','2026-02-02','method','pix')),'42501');
select pg_temp.deny_finance(format('select public.nexo_finance_command(''void_payment'',%L::jsonb)',jsonb_build_object('id',current_setting('finance.payment')::jsonb->>'id','reason','Cross tenant')),'42501');
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select public.nexo_finance_command('void_payment',jsonb_build_object('id',current_setting('finance.payment')::jsonb->>'id','reason','Pagamento lançado incorretamente'));
select pg_temp.check_finance((public.nexo_finance_page('2026-02-01')->'summary'->>'received_cents')='0','correction removed from cash');
select pg_temp.check_finance((public.nexo_finance_page('2026-02-01')->'summary'->>'receivable_cents')='10001','correction restores balance');
select public.nexo_finance_command('void_operation',jsonb_build_object('id',current_setting('finance.sale')::jsonb->>'id','reason','Venda duplicada'));
select pg_temp.check_finance((select count(*) from public.operations where voided_at is not null)=1,'operation retained for audit');
select pg_temp.check_finance((select count(*) from public.payments where void_reason is not null)=1,'payment correction retained for audit');
select pg_temp.check_finance((public.nexo_finance_page('2026-01-01')->'summary'->>'sales_cents')='0','void excluded from revenue');
-- Quote snapshots and idempotent conversion, including manual attempts to forge price.
insert into public.customers(company_id,name) values(current_setting('finance.company_a')::uuid,'Cliente antigo');
select set_config('finance.customer',(select id::text from public.customers limit 1),true);
select set_config('finance.quote',public.nexo_save_quote(jsonb_build_object('company_id',current_setting('finance.company_a'),'request_id',gen_random_uuid(),'customer_id',current_setting('finance.customer'),'title','Serviço aprovado','discount_cents',0,'items',jsonb_build_array(jsonb_build_object('name','Atendimento','unit','un','quantity_milli',1500,'unit_price_cents',999))))::text,true);
select set_config('finance.quote',public.nexo_set_quote_status((current_setting('finance.quote')::jsonb->>'id')::uuid,'sent',(current_setting('finance.quote')::jsonb->>'updated_at')::timestamptz)::text,true);
select pg_temp.deny_finance(format('select public.nexo_finance_command(''convert'',%L::jsonb)',jsonb_build_object('request_id',gen_random_uuid(),'quote_id',current_setting('finance.quote')::jsonb->>'id','occurred_on','2026-01-10','due_on','2026-01-10')),'55000');
select set_config('finance.quote',public.nexo_set_quote_status((current_setting('finance.quote')::jsonb->>'id')::uuid,'approved',(current_setting('finance.quote')::jsonb->>'updated_at')::timestamptz)::text,true);
select set_config('finance.converted',public.nexo_finance_command('convert',jsonb_build_object('request_id',gen_random_uuid(),'quote_id',current_setting('finance.quote')::jsonb->>'id','occurred_on','2026-01-10','due_on','2026-01-10','amount_cents',1))::text,true);
select pg_temp.check_finance((current_setting('finance.converted')::jsonb->>'amount_cents')='1499','converted amount from quote only, exact rounding');
select pg_temp.check_finance(current_setting('finance.converted')::jsonb->'quote_snapshot'->'items' is not null,'line snapshots kept');
select pg_temp.check_finance((public.nexo_finance_command('convert',jsonb_build_object('request_id',gen_random_uuid(),'quote_id',current_setting('finance.quote')::jsonb->>'id','occurred_on','2026-01-10','due_on','2026-01-10'))->>'id')=(current_setting('finance.converted')::jsonb->>'id'),'one operation per quote');
select pg_temp.check_finance((public.nexo_customer_return(30)->>'total')='1','old customer in retention');
-- More than one page must not be downloaded or silently truncated.
do $$ begin for i in 1..35 loop perform public.nexo_finance_command('create',jsonb_build_object('request_id',gen_random_uuid(),'kind','sale','description','Paginação '||i,'category','Serviços','occurred_on','2026-03-01','due_on','2026-03-31','amount_cents',100)); end loop; end; $$;
select pg_temp.check_finance(jsonb_array_length(public.nexo_finance_page('2026-03-01')->'rows')=30,'server returns only 30 rows');
select pg_temp.check_finance(jsonb_array_length(public.nexo_finance_page('2026-03-01','all','',30)->'rows')=5,'last server page');
select pg_temp.check_finance((public.nexo_finance_page('2026-03-01')->>'total')='35','total includes all pages');
set local role anon;
select pg_temp.deny_finance('select public.nexo_finance_page(''2026-01-01'')','42501');
select pg_temp.deny_finance('select * from public.operations','42501');
reset role;
rollback;
select 'PASS: finance RLS, exact balances, partial payments, cash dates, corrections, quote conversion, retention, server pagination and full snapshot' as result;
